def fetch_all_text_messages(access_token, phone_number):
    all_msgs=[]
    page_index=0
    while True:
        page = apis.phone.search_text_messages(access_token=access_token, phone_number=phone_number, page_index=page_index, page_limit=20)
        if not page:
            break
        all_msgs.extend(page)
        page_index += 1
        if page_index>1000:
            break
    return all_msgs

def fetch_all_voice_messages(access_token, phone_number):
    all_msgs=[]
    page_index=0
    while True:
        page = apis.phone.search_voice_messages(access_token=access_token, phone_number=phone_number, page_index=page_index, page_limit=20)
        if not page:
            break
        all_msgs.extend(page)
        page_index += 1
        if page_index>1000:
            break
    return all_msgs

